-- Migration corrective auto-generee : country_code recalcule par geocodage
-- inverse (scripts/fix_country_codes.py). Applique apres le seed.
BEGIN;
CREATE TEMP TABLE _cc(station_id varchar(100), country_code varchar(10));
UPDATE mart.dim_station s SET country_code = c.country_code FROM _cc c WHERE s.station_id = c.station_id AND s.country_code IS DISTINCT FROM c.country_code;
COMMIT;
